// Cashfree Payments on the business's own API keys: orders, payment links, payments, refunds, settlements,
// reconciliation, disputes, offers, saved cards, subscriptions, Easy Split vendors, SoftPOS terminals, downtimes and
// sandbox simulations. actions.json is generated by `bun scripts/openapi-actions.ts cashfree` from the spec Cashfree's
// docs are built from. COVERAGE.md says what's left out (Payouts, a separate product with its own keys).
// The key is CLIENT_ID:CLIENT_SECRET, optionally :sandbox or :production. Without that, test keys (client ID starting
// TEST, or a cfsk_ma_test_ secret) go to sandbox.cashfree.com and everything else to api.cashfree.com.
import { z } from "zod";
import { AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, specActions } from "../openapi";
import { events, receive, triggers, wanted, watch, webhookSetup } from "./triggers";

// the API version every call is made at: the one actions.json was generated from
const VERSION = "2026-01-01";
const HOSTS = { sandbox: "https://sandbox.cashfree.com/pg", production: "https://api.cashfree.com/pg" } as const;
type Env = keyof typeof HOSTS;
const FORMAT = "enter the Client ID and the Client Secret";

export function parseKey(key: string) {
  const [id = "", secret = "", mode = ""] = key.split(":").map((s) => s.trim());
  if (!id || !secret) throw new AppsError(FORMAT);
  const m = mode.toLowerCase();
  const explicit: Env | undefined = m === "sandbox" || m === "test" ? "sandbox" : m === "production" || m === "prod" || m === "live" ? "production" : undefined;
  if (mode && !explicit) throw new AppsError(`pick Sandbox or Production as the mode (got "${mode}")`);
  const env: Env = explicit ?? (/^TEST/i.test(id) || /_test_/i.test(secret) ? "sandbox" : "production");
  return { id, secret, env, explicit: Boolean(explicit) };
}

const headers = (id: string, secret: string) => ({ "x-client-id": id, "x-client-secret": secret, "x-api-version": VERSION });

const api: Api = {
  name: "Cashfree",
  base: HOSTS.production,
  tokenHelp: "Cashfree Merchant Dashboard → Payment Gateway → Developers → API Keys, pasted as CLIENT_ID:CLIENT_SECRET",
  auth: (key) => {
    const { id, secret } = parseKey(key);
    return headers(id, secret);
  },
  url: (key, _base, path) => `${HOSTS[parseKey(key).env]}${path}`,
};

const actions = await specActions(new URL("./actions.json", import.meta.url), api);

// Cashfree has no "list payments" call; its reconciliation report is how recent payments are found, so say so.
const RECENT = "This is how to see recent payments, refunds and disputes: Cashfree has no plain list of payments.";
for (const [name, extra] of [
  ["list_transactions", `${RECENT} Give filters.start_date and filters.end_date as ISO date-times (2026-11-19T00:00:00Z) and pagination.limit (up to 1000); pass the cursor it answers to get the next page.`],
  ["list_settlements", "Dates as ISO date-times (2026-11-19T00:00:00Z); pagination.limit up to 1000, then the cursor it answers for more."],
  ["create_payment_link", "The quickest way to get paid: Cashfree texts and emails the link_url to the customer when link_notify says so. Amounts are in rupees (500.5 is ₹500.50), not paise."],
  ["create_order", "Amounts are in rupees (500.5 is ₹500.50), not paise. For a link to send a customer, create_payment_link is simpler."],
  ["create_refund", "Amounts are in rupees. Moves money back to the customer: check the order with get_order first."],
] as const) {
  const a = actions[name];
  if (a) a.description = `${a.description} ${extra}`;
}

const setup = {
  get_webhook_setup: {
    description:
      "Where to add Emplio's address in Cashfree so Cashfree's triggers (payment_success, refund_processed, settlement_success…) work. Cashfree takes webhooks only in its own dashboard, so the owner does this once by hand; tell them the address and what to tick exactly as this answers.",
    input: z.object({}),
    readOnly: true,
    run: async (_input: Record<string, unknown>, key: string, connection?: string) => webhookSetup(connection, parseKey(key).env === "sandbox"),
  },
};

// Cashfree has no "who am I". A made-up order is its cheapest call that needs a working key: 404 means the key works.
async function accepted(id: string, secret: string, env: Env) {
  const res = await fetch(`${HOSTS[env]}/orders/emplio-key-check`, { headers: headers(id, secret) });
  if (res.status === 401 || res.status === 403) return false;
  if (res.ok || res.status === 404) return true;
  const body = (await res.json().catch(() => ({}))) as { message?: string };
  throw new AppsError(`Cashfree: ${body.message ?? res.statusText} (${res.status})`);
}

export const cashfree: OwnApp = {
  app: "cashfree",
  name: "Cashfree",
  logo: "/logos/cashfree.svg",
  keyField: {
    label: "Client ID and Client Secret",
    help: "Cashfree Merchant Dashboard → Payment Gateway → Developers → API Keys → Generate API Keys (switch to Test mode first for sandbox keys). Test keys are spotted by themselves; pick the mode only if Emplio guesses wrong.",
    placeholder: "CF12345abcdef:cfsk_ma_prod_xxxxxxxxxxxx",
    sep: ":",
    parts: [{label:"Client ID",placeholder:"CF12345abcdef"},{label:"Client Secret",secret:true,placeholder:"cfsk_ma_prod_xxxxxxxxxxxx"},{label:"Mode",optional:true,options:[{value:"",label:"Tell from the keys"},{value:"sandbox",label:"Sandbox (test)"},{value:"production",label:"Production"}]}],
  },
  async check(key) {
    const { id, secret, env, explicit } = parseKey(key);
    const label = `${env === "sandbox" ? "Sandbox (test)" : "Production"} · ${id.slice(0, 8)}…`;
    if (await accepted(id, secret, env)) return label;
    const other: Env = env === "sandbox" ? "production" : "sandbox";
    if (!explicit && (await accepted(id, secret, other))) throw new AppsError(`these are ${other} keys: connect again and pick ${other} as the mode`);
    throw new AppsError(`Cashfree didn't accept this Client ID and Client Secret for ${env}. Check both were copied in full from Developers → API Keys`);
  },
  actions: { ...actions, ...setup },
  push: { events, triggers, wanted, receive: (delivery, key) => receive(delivery, parseKey(key).secret), start: (_key, connection) => watch(connection) },
};
